import{_ as n,o as e,c as t,aw as i}from"./chunks/framework.DLufY-ao.js";const b=JSON.parse('{"title":"Kanban","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/models/kanban.md","filePath":"wiki/dev-commit/theory/agile/models/kanban.md"}'),l={name:"wiki/dev-commit/theory/agile/models/kanban.md"};function o(s,a,r,c,d,m){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Kanban</p><ul><li><strong>Kanban</strong> - «подход баланса». Гибкий метод управления проектами, целью которого является повышение производительности труда в командах</li></ul></div><ul><li><strong>Главная идея Kanban</strong> - визуализация рабочего процесса. Она заключается в создании физической панели, на которой можно наглядно отмечать прогресс</li><li>Задача – сбалансировать разных специалистов внутри команды и избежать ситуации, когда дизайнеры работают сутками, а разработчики жалуются на отсутствие новых задач</li><li>Вся команда едина – в kanban нет ролей владельца продукта и scrum-мастера. Бизнес-процесс делится не на универсальные спринты, а на стадии выполнения конкретных задач: «Планируется», «Разрабатывается», «Тестируется», «Завершено» и др.</li><li>Главный показатель эффективности в kanban – это среднее время прохождения задачи по доске. Задача прошла быстро – команда работала продуктивно и слаженно. Задача затянулась – надо думать, на каком этапе и почему возникли задержки и чью работу надо оптимизировать</li><li>Для визуализации agile-подходов используют доски: физические и электронные. Они позволяют сделать рабочий процесс открытым и понятным для всех специалистов, что важно, когда у команды нет одного формального руководителя</li></ul>',3)])])}const k=n(l,[["render",o]]);export{b as __pageData,k as default};
